const pi = 3.1416;
let puntuacion = 100;

// Arrow function compacta con retorno implícito
const calcularCuadrado = x => x * x;
console.log(calcularCuadrado(4)); // Imprime 16

ejercicio_practico.solucion_paso_a_paso:
Paso 1: Define la arrow function con parámetros por defecto: const calcularDescuento = (precio, descuento = 10) => ...
Paso 2: Realiza la operación matemática dentro de la función: precio - (precio * (descuento / 100)).
Paso 3: Retorna el resultado implícitamente en una sola línea: const calcularDescuento = (precio, descuento = 10) => precio * (1 - descuento / 100);

